rules.callback:
lambda ctx, r: f'  br label %loop_entry_{range_str(r)}
loop_entry_{range_str(r)}:
  br label %loop_latch_{range_str(r)}
loop_latch_{range_str(r)}:
  {ctx[r]} = phi {ldt(r.dtype)} [ 0, %loop_entry_{range_str(r)} ], [ {ctx[r]}phi, %loop_footer_{range_str(r)} ]
  {ctx[r]}phi = add {ldt(r.dtype)} {ctx[r]}, 1
  {ctx[r]}cmp = icmp ult {ldt(r.dtype)} {ctx[r]}, {ctx[r.src[0]]}
  br i1 {ctx[r]}cmp, label %loop_body_{range_str(r)}, label %loop_exit_{range_str(r)}
loop_body_{range_str(r)}:'

lambda r: f'  br label %loop_footer_{range_str(r)}
loop_footer_{range_str(r)}:
  br label %loop_latch_{range_str(r)}
loop_exit_{range_str(r)}:'
